drop table if exists t3;
create table t3 (id int primary key, v1 varchar(20000), v2 varchar(20000));
insert into t3 values (1, repeat('a', 8000), repeat('b', 8000)), (2, repeat('c', 9000), repeat('d', 9000));
create index i3 on t3 (v1, v2, id);
update t3 set v1 = repeat('e', 8500) where id = 1;
delete from t3 where id = 2;
select id, length(v1), length(v2) from t3 order by id;
drop table if exists t4;
create table t4 (id int primary key, a int);
insert into t4 values (1,1),(2,2),(3,3);
alter table t4 add column ch char(3000) default 'a';
alter table t4 add column ch2 char(2000) default 'b';
create index i4 on t4 (ch, ch2, id);
update t4 set a = a + 1;
delete from t4 where id = 2;
drop table if exists t5;
create table t5 (id int primary key, v varchar(10));
insert into t5 values (1,'a'),(2,'b');
alter table t5 modify v varchar(5000);
alter table t5 add column c varchar(6000) default repeat('y', 4500);
create index i5 on t5 (v, c, id);
update t5 set v = 'q' where id = 1;
delete from t5 where id = 2;
drop table if exists t6;
create table t6 (id int primary key, a varchar(20));
insert into t6 values (1,'x'),(2,'y'),(3,'z');
alter table t6 add column c varchar(5000) default repeat('w', 4300);
create index i6 on t6 (c, id, upper(a));
update t6 set a = 'k' where id = 1;
delete from t6 where id = 2;
drop table if exists c7; drop table if exists p7;
create table p7 (id int, c varchar(5000), primary key (c, id));
insert into p7 values (1, repeat('x', 4200)), (2, repeat('x', 4200));
create table c7 (id int primary key, pid int);
insert into c7 values (1,1),(2,2);
alter table c7 add column c varchar(5000) default repeat('x', 4200);
alter table c7 add constraint fk7 foreign key (c, pid) references p7 (c, id) on delete cascade;
delete from p7 where id = 1;
select count(*) from c7;
